        if not nested:
            # [ts1, ts2] -> [[ts1, ts2]]
            return [ts]
        else:
            # [ts1, ts2] -> [[ts1], [ts2]]
            return [[ts_] for ts_ in ts]
    elif (
        seq_type_in == SeriesType.SEQ_SEQ
        and seq_type_out == SeriesType.SINGLE
        and n_series == 1
    ):
        # [[ts]] -> [ts]
