        super().__init__(add_encoders=add_encoders, min_train_length=min_train_length)
        self.value = value
    @property
    def supports_multivariate(self): return False
    def fit(self, series, verbose=None):
        super().fit(series, verbose=verbose)
        return self
    def predict(self, n, num_samples=1, verbose=None, show_warnings=True, random_state=None):
        return self._build_forecast_series(np.full((n,1), self.value))

