import numpy as np, pandas as pd
from darts import TimeSeries, metrics
from darts.models.forecasting.forecasting_model import LocalForecastingModel, GlobalForecastingModel

class LocalRepeat(LocalForecastingModel):
    def __init__(self, add_encoders=None, value=0.0, min_train_length=None):
        super().__init__(add_encoders=add_encoders, min_train_length=min_train_length)
        self.value = value
    @property
    def supports_multivariate(self): return False
    def fit(self, series, verbose=None):
        super().fit(series, verbose=verbose)
        return self
    def predict(self, n, num_samples=1, verbose=None, show_warnings=True, random_state=None):
        return self._build_forecast_series(np.full((n,1), self.value))

class GlobalRepeat(GlobalForecastingModel):
    def __init__(self, add_encoders=None, value=0.0):
        super().__init__(add_encoders=add_encoders)
        self.value=value
    @property
    def supports_multivariate(self): return True
    def fit(self, series, past_covariates=None, future_covariates=None, verbose=None):
        super().fit(series, past_covariates=past_covariates, future_covariates=future_covariates, verbose=verbose)
        return self
    def predict(self, n, series=None, past_covariates=None, future_covariates=None, num_samples=1, verbose=None, predict_likelihood_parameters=False, show_warnings=True, random_state=None):
        super().predict(n, series=series, past_covariates=past_covariates, future_covariates=future_covariates, num_samples=num_samples, verbose=verbose, predict_likelihood_parameters=predict_likelihood_parameters, show_warnings=show_warnings, random_state=random_state)
        s=series if series is not None else self.training_series
        if isinstance(s, (list,tuple)):
            return [self._build_forecast_series(np.full((n,1),self.value), input_series=x) for x in s]
        return self._build_forecast_series(np.full((n,1),self.value), input_series=s)

series=TimeSeries.from_times_and_values(pd.date_range('2020-01-01',periods=10,freq='D'), np.arange(10.)[:,None])
