print('backtest nanred',m.backtest(series,start=3,start_format='position',forecast_horizon=1,metric=metrics.mae,reduction=None))
print('residuals',m.residuals(series,start=3,start_format='position'))
print('residuals vals',m.residuals(series,start=3,start_format='position',values_only=True))
try:
