import numpy as np, warnings
warnings.filterwarnings('ignore')
from darts import TimeSeries
from darts.models import SKLearnModel
from sklearn.linear_model import LinearRegression
from sklearn.svm import SVR

# get_estimator after wrapper
s=TimeSeries.from_values(np.arange(40,dtype=float).reshape(-1,2))
m=SKLearnModel(lags=2, output_chunk_length=2, model=SVR())
m.fit(s)
print(type(m.model), len(m.model.estimators_))
for h in range(2):
 for d in range(2):
  e=m.get_estimator(h,d)
  print(h,d,type(e).__name__, e is m.model.estimators_[m.input_dim['target']*h+d])
for args in [(-1,0),(2,0),(0,-1),(0,2)]:
 try: m.get_estimator(*args); print('no error',args)
 except Exception as e: print(args,type(e).__name__,str(e).split('\n')[0])
# non multioutput mixin
m2=SKLearnModel(lags=2)
try: print('non mixin',m2.get_estimator(99,99))
except Exception as e: print('err',e)
# quantile error
try: m2.get_estimator(0,0,quantile=.5)
except Exception as e: print('q err',type(e).__name__,e)
# fit multiple series / prediction without series
s1=TimeSeries.from_values(np.arange(20,dtype=float).reshape(-1,1))
s2=TimeSeries.from_values(np.arange(100,120,dtype=float).reshape(-1,1))
m=SKLearnModel(lags=2); m.fit([s1,s2]); print('multi p',m.predict(2).values().ravel())
try: print(m.predict(2,series=[s1,s2]).values().shape)
except Exception as e: print('list pred err',type(e).__name__,e)
print(type(m.predict(2, series=[s1,s2])), type(m.predict(2,series=s1)))
# fit error cov contracts
for tryit in ['past_no_lags','none_cov','past_none']:
 try:
  m=SKLearnModel(lags=2,lags_past_covariates=2) if tryit=='past_no_lags' else SKLearnModel(lags=2)
  if tryit=='past_no_lags': m.fit(s1,past_covariates=s1)
  elif tryit=='none_cov': m.fit(s1,past_covariates=None)
  else: m.fit(s1)
  if tryit=='none_cov': pass
  print('no err',tryit)
 except Exception as e: print(tryit,type(e).__name__,str(e).split('\n')[0])
PY"}

