from darts import TimeSeries
from darts.models import SKLearnModel
n=40
target=TimeSeries.from_values(np.arange(n,dtype=float).reshape(-1,1))
ts=TimeSeries.from_values(np.arange(n,dtype=float).reshape(-1,1), static_covariates=pd.DataFrame({'a':[1.], 'b':[2.]}))
