m=SKLearnModel(lags=2); m.fit(ts); p=m.predict(2); print('static pred',p.static_covariates,p.values().ravel()); print('static names',m.lagged_feature_names,m.lagged_label_names)
m2=SKLearnModel(lags=2,use_static_covariates=False);m2.fit(ts);p2=m2.predict(2); print('no static',p2.static_covariates,m2.lagged_feature_names)
print('uses_static',m.uses_static_covariates,m._uses_static_covariates)

