for desc,kw in [('width target', {'series':TimeSeries.from_values(np.arange(20).reshape(-1,2).astype(float))}),('short',{'series':target[:1]})]:
 try: m.predict(2,**kw); print('no err',desc)
 except Exception as e: print(desc,type(e).__name__,str(e).split('\n')[0])
for desc,model,args in [
