"""Behavioral tests for the sklearn-backed forecasting models."""

import logging

import numpy as np
import pandas as pd
import pytest
from sklearn.base import BaseEstimator, ClassifierMixin, RegressorMixin
from sklearn.linear_model import LinearRegression, LogisticRegression
from sklearn.svm import SVR

from darts import TimeSeries
from darts.models.forecasting.sklearn_model import (
    RegressionModel,
    SKLearnClassifierModel,
    SKLearnModel,
    SKLearnModelWithCategoricalFeatures,
)
from darts.utils.multioutput import MultiOutputRegressor


class RecordingRegressor(RegressorMixin, BaseEstimator):
    """Small sklearn-compatible regressor that exposes what Darts passes to fit/predict."""

    def __init__(self, prediction=0.0):
        self.prediction = prediction

    def fit(self, X, y, sample_weight=None, **kwargs):
        self.X_ = np.asarray(X)
        self.y_ = np.asarray(y)
        self.sample_weight_ = (
            None if sample_weight is None else np.asarray(sample_weight)
        )
        self.fit_kwargs_ = kwargs
        return self

    def predict(self, X, **kwargs):
        self.predict_kwargs_ = kwargs
        return np.full(len(X), self.prediction, dtype=float)


class NoWeightRegressor(RegressorMixin, BaseEstimator):
    def fit(self, X, y):
        self.X_ = np.asarray(X)
        return self

    def predict(self, X):
        return np.zeros(len(X), dtype=float)


class UniformClassifier(ClassifierMixin, BaseEstimator):
    """Classifier that can fit even when a target slice contains a single class."""

    def fit(self, X, y):
        self.classes_ = np.unique(y)
        self.n_features_in_ = np.asarray(X).shape[1]
        return self

    def predict(self, X):
        return np.full(len(X), self.classes_[0], dtype=float)

    def predict_proba(self, X):
        proba = np.zeros((len(X), len(self.classes_)))
        proba[:, 0] = 1.0
        return proba


class NoProbaClassifier(ClassifierMixin, BaseEstimator):
    def fit(self, X, y):
        self.classes_ = np.unique(y)
        return self

    def predict(self, X):
        return np.full(len(X), self.classes_[0], dtype=float)


class CategoricalRegressor(SKLearnModelWithCategoricalFeatures):
    @property
    def _categorical_fit_param(self):
        return None

